alter table public.knowledge_lesson_attachments rename column file_url to object_path;
alter table public.knowledge_lesson_attachments drop constraint if exists knowledge_lesson_attachments_file_url_check;
alter table public.knowledge_lesson_attachments add constraint knowledge_lesson_attachments_object_path_check check (object_path ~ '^[0-9]+/[0-9a-f-]+[.]pdf$');
insert into storage.buckets (id,name,public,file_size_limit,allowed_mime_types) values ('course-attachments','course-attachments',false,5242880,array['application/pdf']) on conflict (id) do update set public=false,file_size_limit=excluded.file_size_limit,allowed_mime_types=excluded.allowed_mime_types;
create policy "Learners can download course attachments" on storage.objects for select to authenticated using (bucket_id='course-attachments' and exists (select 1 from public.knowledge_lesson_attachments attachment join public.knowledge_lessons lesson on lesson.id=attachment.lesson_id join public.knowledge_products product on product.id=lesson.product_id where attachment.object_path=storage.objects.name and lesson.status='published' and product.status='published' and (public.is_admin_or_moderator() or lesson.free_preview or product.price=0 or exists(select 1 from public.knowledge_access access where access.product_id=product.id and access.user_id=auth.uid()) or exists(select 1 from public.knowledge_memberships membership where membership.user_id=auth.uid() and (membership.expires_at is null or membership.expires_at>now())))));
create policy "Editors can upload course attachments" on storage.objects for insert to authenticated with check (bucket_id='course-attachments' and public.is_admin_or_moderator());
create policy "Editors can delete course attachments" on storage.objects for delete to authenticated using (bucket_id='course-attachments' and public.is_admin_or_moderator());
